// Existing purchase IDs, storage state and engine actions are the sole source of truth.
export function parcelGuideHTML(s,{E,esc}){
 const carried=E.carried(s),checked=E.owned(s).filter(i=>i.checked);
 return `<section class="parcel-guide" aria-label="Parcel check"><span class="eyebrow">YOUR PURCHASED PARCELS</span><h3>Free your hands between shops.</h3><p class="parcel-tally" role="status"><strong>${carried.length}/8 carried</strong> · ${checked.length} checked at guest services</p><p>Check today’s carried purchases for free, then collect each parcel before using, delivering or returning it. Unpaid shop selections stay in your shopping bag; they are not deposited here.</p><button class="button orange wide" data-action="check-packages" ${carried.length?'':'disabled'}>Check ${carried.length} carried purchase${carried.length===1?'':'s'} · free · 5 min</button><h4>Your checked purchases</h4>${checked.length?checked.map(i=>{const p=E.byId(i.productId),st=E.storeById(i.store||p.store);return `<article class="package-row"><div><strong>${esc(p.name)}</strong><small>${esc(i.size)} · ${esc(st.name)} · purchased day ${i.day}</small></div><button class="button secondary" data-action="collect-package" data-id="${esc(i.id)}" ${carried.length>=8?'disabled':''}>Collect · 3 min</button></article>`;}).join(''):'<p>No parcels waiting. Check a purchased item here after checkout.</p>'}${carried.length>=8&&checked.length?'<p class="hint">Your hands are full. Check your carried purchases before collecting another parcel.</p>':''}<p class="hint">Checked parcels stay with the game’s shared concierge between centers. Remaining parcels go home automatically when you sleep. This is a game service, not a real mall policy.</p><button class="button secondary wide" data-action="view" data-id="receipts">Review receipts & return deadlines</button></section>`;
}
export function updateParcelDesk(w){
 if(!w.parcelDesk)return;const count=w.state.purchases.filter(i=>i.checked&&!i.returned&&!i.delivered).length;
 if(w.parcelDesk.count===count)return;w.parcelDesk.count=count;w.parcelDesk.groups.forEach((g,i)=>g.visible=i<Math.min(3,count));w.canvas.dataset.parcelDeskRevision='60';w.canvas.dataset.checkedParcelCount=String(count);
}
